package com.axiom.application.testreport; import com.axiom.domain.test.*; import com.axiom.integrations.testreport.TestReportParser; import java.security.*;import java.util.*;import java.util.UUID;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TestReportIngestionService {private final TestReportParser parser;private final JdbcTemplate jdbc;public TestReportIngestionService(TestReportParser p,JdbcTemplate j){parser=p;jdbc=j;}@Transactional public Map<String,Object> ingest(UUID run,String source,byte[] content,String hint){TestReport report=parser.parse(source,content,hint);String hash=hash(content);UUID id=jdbc.query("select id from test_reports where pipeline_run_id=? and source_name=? and content_sha256=?",rs->rs.next()?(UUID)rs.getObject(1):null,run,source,hash);if(id!=null)return Map.of("testReportId",id,"pipelineRunId",run,"totalTests",report.total(),"idempotent",true);id=UUID.randomUUID();int passed=0,failed=0,errors=0,skipped=0;for(var s:report.suites())for(var t:s.testCases())switch(t.status()){case PASSED->passed++;case FAILED->failed++;case ERROR->errors++;case SKIPPED,DISABLED->skipped++;default->{}}jdbc.update("insert into test_reports(id,pipeline_run_id,source_name,framework_hint,content_sha256,total_tests,passed,failed,errors,skipped) values(?,?,?,?,?,?,?,?,?,?)",id,run,source,hint,hash,report.total(),passed,failed,errors,skipped);for(var s:report.suites()){UUID sid=UUID.randomUUID();jdbc.update("insert into test_suites(id,test_report_id,name) values(?,?,?)",sid,id,s.name());for(var t:s.testCases())jdbc.update("insert into test_case_executions(id,test_suite_id,pipeline_run_id,stable_test_id,test_id_algorithm,class_name,test_name,status,duration_ms,failure_type,failure_message,normalized_failure_message,stack_trace) values(?,?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),sid,run,t.stableTestId(),"test-id-v1",t.className(),t.testName(),t.status().name(),t.durationMs(),t.failureType(),t.failureMessage(),t.normalizedFailureMessage(),t.stackTrace());}return Map.of("testReportId",id,"pipelineRunId",run,"totalTests",report.total(),"passed",passed,"failed",failed,"errors",errors,"skipped",skipped,"suiteCount",report.suites().size());}private String hash(byte[] b){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new IllegalStateException(e);}}}
